import {addMonths} from './timeline.js';
import {CalculatorError} from './calculator-params.js';
export const FINANCIAL_VERSION='2026-11-22.2';
const cents=n=>Math.round((Number(n)+Number.EPSILON)*100);
export function allocateFuneral(payers,limit){if(!Array.isArray(payers)||payers.length<2||payers.length>20)throw new CalculatorError('Podaj od 2 do 20 osób / podmiotów ponoszących koszty.');const ids=new Set();const rows=payers.map((p,i)=>{const id=String(p.id||'payer-'+i).slice(0,70),cost=cents(p.cost);if(ids.has(id)||!Number.isFinite(cost)||cost<=0||!['family','other'].includes(p.relation))throw new CalculatorError('Każdy płatnik potrzebuje odrębnego oznaczenia, relacji i dodatnich kosztów.');ids.add(id);return {id,relation:p.relation,cost};}),total=rows.reduce((n,p)=>n+p.cost,0),cap=cents(limit),allFamily=rows.every(p=>p.relation==='family'),allOther=rows.every(p=>p.relation==='other');
 if(!allFamily&&!allOther&&total<cap)return {complete:false,reason:'Przy mieszanym pokrewieństwie i kosztach niższych od pełnego świadczenia potrzebne jest potwierdzenie łącznej kwoty podziału przez ZUS.',allocations:[]};
 const pool=allOther?Math.min(total,cap):cap;
 const shares=rows.map(p=>({...p,numerator:pool*p.cost,share:Math.floor(pool*p.cost/total)}));let remainder=pool-shares.reduce((n,p)=>n+p.share,0);const order=[...shares].sort((a,b)=>(b.numerator%total)-(a.numerator%total)||a.id.localeCompare(b.id));for(let i=0;i<remainder;i++)order[i%order.length].share++;
 return {complete:true,pool:pool/100,totalCosts:total/100,allocations:shares.map(p=>({id:p.id,relation:p.relation,cost:p.cost/100,amount:p.share/100})),algorithm:FINANCIAL_VERSION,legalBasis:'art.78 ust.2–3 i art.80 ustawy o emeryturach i rentach z FUS',rounding:'Podział w groszach, największe reszty; suma udziałów jest dokładnie równa puli.'};}
export function equalizationProjection(result,today){const d=result.input.formalCase;if(d.equalizationRequested!=='yes')return null;const anniversary=addMonths(result.input.eventDate,12),history=result.input.historyParentalPeriods||[],usedFirstYear=history.filter(p=>p.start<anniversary&&p.end>=result.input.eventDate),proposedFirstYear=result.periods.filter(p=>(p.id.startsWith('parental')||p.id.startsWith('extension'))&&p.start<anniversary&&p.end>=result.input.eventDate);if([...usedFirstYear,...proposedFirstYear].some(p=>p.rate===81.5||p.rate==null))return {amount:null,conditional:true,missing:'Historia albo ten plan obejmuje rodzicielski w pierwszym roku ze stawką 81,5% lub nieustaloną. Uzgodnij go z potwierdzeniem niewykorzystania; wyrównania nie doliczamy.'};const parent=d.equalizationParent||0,periods=result.periods.filter(p=>p.parent===parent&&p.id.startsWith('maternity')&&p.rate===81.5);if(today<addMonths(result.input.eventDate,12)||!periods.length||periods.some(p=>p.gross===null||p.basis==null)||d.actualMaternityGross==null||d.actualPaymentConfirmed!=='yes'||d.noParentalFirstYear!=='yes'||!d.historyComplete)return {amount:null,parent,conditional:true,missing:'Potrzebna jest historia macierzyńskiego w wariancie 81,5%, jego rzeczywista kwota brutto, podstawa oraz potwierdzenie pierwszego roku.'};const full=periods.reduce((n,p)=>n+cents(p.basis/30)*p.days,0),paid=cents(d.actualMaternityGross);if(paid>full)return {amount:null,parent,conditional:true,missing:'Rzeczywista kwota przewyższa odtworzoną kwotę 100%; sprawdź okres i podstawę. Nie uznajemy decyzji ZUS za błędną.'};return {amount:(full-paid)/100,parent,fullGross:full/100,actualGross:paid/100,conditional:true,legalBasis:'art.31 ust.4 ustawy zasiłkowej',description:'Wariant wyrównania brutto na wniosek, po potwierdzeniu pełnej historii. Nie jest nową wypłatą ani zmianą zapisanej decyzji.'};}
export function payoutProjection(gross,{taxAdvance,healthDeduction,otherDeductions,wage=false}={}){if(gross==null||taxAdvance==null||otherDeductions==null||wage&&healthDeduction==null)return {net:null,kind:'missing',reason:'Podaj znane potrącenia właściwego płatnika. Nie obliczamy PIT całej osoby z samej podstawy zasiłku.'};const values=[gross,taxAdvance,healthDeduction||0,otherDeductions];if(values.some(n=>!Number.isFinite(Number(n))||n<0))throw new CalculatorError('Sprawdź kwoty potrąceń.');const net=cents(gross)-cents(taxAdvance)-cents(healthDeduction||0)-cents(otherDeductions);if(net<0)throw new CalculatorError('Potrącenia przekraczają kwotę brutto.');return {net:net/100,kind:'declared-deductions',gross,description:'Wyliczenie z podanych potrąceń, nie potwierdzenie przelewu. Składki finansowane z budżetu od macierzyńskiego nie są ponownym potrąceniem 13,71% z tej kwoty.'};}
